function elevAt(x,y){x=clamp(x,0,N-.001);y=clamp(y,0,N-.001);const xi=x|0,yi=y|0,fx=x-xi,fy=y-yi,M=N+1,a=hv[yi*M+xi],b=hv[yi*M+xi+1],c=hv[(yi+1)*M+xi],d=hv[(yi+1)*M+xi+1];return Math.max(a+(b-a)*fx+(c-a)*fy+(a-b-c+d)*fx*fy,0)*.5}
function s2w(px,py,z){let u=(px-W/2)/HW,v=(py-H*.5+((z||0)-camZ)*HZ)/HH;const e=elevAt(camX+(u+v)/2,camY+(v-u)/2);v=(py-H*.5+((z||0)+e-camZ)*HZ)/HH;return[camX+(u+v)/2,camY+(v-u)/2]}
const light=()=>.5+.5*Math.sin(2*Math.PI*(T.time/DAYLEN-.25));
