 if(!boss&&d<9&&!P.dead){boss=spawnEnemy('guardian',altar.x,altar.y);boss.prov=true;boss.state='chase';boss.cd=1.5;toast('¡El Guardián de Raíces despierta!',3000);snd(70,.8,'sawtooth',.1,-20)}
