function blood(x,y,z,n){for(let i=0;i<n;i++)parts.push({x,y,z,vx:rr(-2.2,2.2),vy:rr(-2.2,2.2),vz:rr(1,4.5),t:rr(.6,1.2),col:rnd()<.5?'#a01818':'#7c0e0e',s:rr(2,4),bl:1})}
