function burst(x,y,z,col,n){for(let i=0;i<n;i++)parts.push({x,y,z,vx:rr(-1.8,1.8),vy:rr(-1.8,1.8),vz:rr(1,4),t:rr(.4,.8),col,s:rr(2,4)})}
