function revealAround(){const cx=P.x|0,cy=P.y|0;let ch=false;for(let y=cy-7;y<=cy+7;y++)for(let x=cx-7;x<=cx+7;x++){if(x<0||y<0||x>=N||y>=N||(x-P.x)**2+(y-P.y)**2>49)continue;const i=y*N+x;if(!explored[i]){explored[i]=1;paintMM(i);ch=true}}if(ch)mmDirty=true}
