function poly(a,b,c,d,e,f,g,h){ctx.beginPath();ctx.moveTo(a,b);ctx.lineTo(c,d);ctx.lineTo(e,f);if(g!==undefined)ctx.lineTo(g,h);ctx.closePath();ctx.fill()}
