 const Ax=sX(x,y),Ay=sY(x,y,z1),Bx=sX(x1,y),By=sY(x1,y,z1),Cx=sX(x1,y1),Cy=sY(x1,y1,z1),Dx=sX(x,y1),Dy=sY(x,y1,z1);
 const B0x=sX(x1,y),B0y=sY(x1,y,z),C0x=sX(x1,y1),C0y=sY(x1,y1,z),D0x=sX(x,y1),D0y=sY(x,y1,z);
