let SUN=null;const SILS={},AMB=[[0,[30,40,88]],[.18,[36,48,100]],[.24,[120,100,130]],[.28,[255,176,125]],[.33,[255,222,180]],[.4,[255,250,235]],[.5,[255,255,250]],[.6,[255,250,235]],[.68,[255,226,182]],[.73,[255,168,120]],[.77,[130,92,120]],[.82,[44,54,104]],[.9,[32,42,90]],[1,[30,40,88]]];
function ambient(){const p=T.time/DAYLEN;for(let i=1;i<AMB.length;i++){if(p<=AMB[i][0]){const a=AMB[i-1],b=AMB[i],t=(p-a[0])/(b[0]-a[0]);return[0,1,2].map(k=>a[1][k]+(b[1][k]-a[1][k])*t)}}return AMB[0][1]}
function sunShadow(){const l=light();return{sx:.72,sy:.3,a:.14+.24*clamp((l-.25)*2.2,0,1)}}
function drawWallShadows(){if(!SUN||SUN.a<.03||!cPieces)return;ctx.save();ctx.fillStyle='rgba(0,0,0,'+(SUN.a*.85)+')';ctx.beginPath();let any=false;
 for(const b of blocks.values()){const t=BT[b.type];if(!b.c||!t.wall)continue;const g=wallGeom(b),pc=pieceCenter(b);zoff=elevAt(pc[0],pc[1]);const zb=b.z*WH,ht=(zb+WH)*HZ,dx=SUN.sx*ht,dy=SUN.sy*ht,a=g.ax?[g.c,g.s]:[g.s,g.c],c=g.ax?[g.c,g.e]:[g.e,g.c];
  const A=[sX(a[0],a[1]),sY(a[0],a[1],0)],C=[sX(c[0],c[1]),sY(c[0],c[1],0)];if(A[0]<-W*.5||A[0]>W*1.5||A[1]<-H*.5||A[1]>H*1.6)continue;const db=SUN.sx*zb*HZ,eb=SUN.sy*zb*HZ;ctx.moveTo(A[0]+db,A[1]+eb);ctx.lineTo(C[0]+db,C[1]+eb);ctx.lineTo(C[0]+dx,C[1]+dy);ctx.lineTo(A[0]+dx,A[1]+dy);ctx.closePath();any=true}
 zoff=0;if(any)ctx.fill();ctx.restore()}
function drawNight(){
 const am=ambient(),lw=Math.ceil(W/2),lh=Math.ceil(H/2);
 if(Math.min(am[0],am[1],am[2])<250){
  if(lc.width!==lw||lc.height!==lh){lc.width=lw;lc.height=lh}
  lx.setTransform(1,0,0,1,0,0);lx.globalCompositeOperation='source-over';lx.fillStyle='rgb('+(am[0]|0)+','+(am[1]|0)+','+(am[2]|0)+')';lx.fillRect(0,0,lw,lh);lx.globalCompositeOperation='lighter';
  const lit=(wx,wy,rad,k,c)=>{zoff=elevAt(wx,wy);const X=sX(wx,wy)/2,Y=sY(wx,wy,.5)/2;zoff=0;const R=rad*HW*.7,g=lx.createRadialGradient(X,Y,R*.05,X,Y,R),fk=1+Math.sin(T.time*13+wx*3)*.05;g.addColorStop(0,'rgba('+c+','+k*fk+')');g.addColorStop(.45,'rgba('+c+','+k*.45+')');g.addColorStop(1,'rgba('+c+',0)');lx.save();lx.translate(X,Y);lx.scale(1,.62);lx.translate(-X,-Y);lx.fillStyle=g;lx.fillRect(X-R,Y-R,R*2,R*2);lx.restore()};
  if(!P.dead)lit(P.x,P.y,3.2,.55,'255,196,130');
  for(const b of stations)if(b.type==='hoguera')lit(b.x+.5,b.y+.5,7.5,1,'255,170,90');else if(b.type==='forja')lit(b.x+.5,b.y+.5,4.5,.9,'255,130,60');
  ctx.save();ctx.globalCompositeOperation='multiply';ctx.drawImage(lc,0,0,W,H);ctx.restore()}
 ctx.save();ctx.globalCompositeOperation='lighter';
 for(const b of stations)if(b.type==='hoguera'||b.type==='forja'){zoff=elevAt(b.x+.5,b.y+.5);const X=sX(b.x+.5,b.y+.5),Y=sY(b.x+.5,b.y+.5,.45);zoff=0;const R=HW*(b.type==='forja'?1.3:1.7),g=ctx.createRadialGradient(X,Y,2,X,Y,R);g.addColorStop(0,'rgba(255,170,70,'+(.34+Math.sin(T.time*15+b.x)*.05)+')');g.addColorStop(1,'rgba(255,120,30,0)');ctx.fillStyle=g;ctx.fillRect(X-R,Y-R,R*2,R*2)}
 ctx.restore();
 const dk=clamp((light()-.55)*3,0,1);if(dk>0){ctx.save();ctx.globalCompositeOperation='lighter';ctx.fillStyle='rgba(255,236,170,'+(.07*dk)+')';ctx.fillRect(0,0,W,H);ctx.restore()}
 const vg=ctx.createRadialGradient(W/2,H/2,Math.min(W,H)*.35,W/2,H/2,Math.max(W,H)*.75);vg.addColorStop(0,'rgba(0,0,0,0)');vg.addColorStop(1,'rgba(0,0,0,'+(.16+.3*(1-Math.min(1,light()*1.6)))+')');ctx.fillStyle=vg;ctx.fillRect(0,0,W,H)}
