function openSheet(tab){sheetTab=tab||sheetTab;$('sheet').classList.add('on');renderSheet()}
function closeSheet(){$('sheet').classList.remove('on');chestOpen=null}
function costHTML(cost){return Object.keys(cost).map(id=>`<span class="${have(id)>=cost[id]?'':'bad'}">${cost[id]}${IT[id][1]}</span>`).join(' ')}
function renderSheet(){
 const tabs=[['bag','🎒 Mochila'],['craft','🛠 Crear'],['guide','📖 Guía'],['menu','⚙ Menú']];if(chestOpen)tabs.splice(2,0,['chest','📦 Cofre']);if(sheetTab==='st'&&stOpen)tabs.splice(2,0,['st','🛠 '+BT[stOpen].n]);
 if(sheetTab==='chest'&&!chestOpen)sheetTab='bag';if(sheetTab==='st'&&!stOpen)sheetTab='bag';
 let h='<div class="tabs">'+tabs.map(([k,l])=>`<button data-a="tab" data-k="${k}" class="${k===sheetTab?'on':''}">${l}</button>`).join('')+'<button class="x" data-a="close">✕</button></div>';
 if(sheetTab==='bag'){
  const ids=Object.keys(P.inv).filter(k=>P.inv[k]>0),w=WEAP[P.weapon];
  h+=`<div class="mut" style="margin-bottom:8px">Arma: <b>${w.e} ${w.n}</b>${P.inv.escudo?' · 🛡️ escudo':''}${P.inv.capa?' · 🧥 capa':''} · Hacha y pico se equipan solos al golpear árboles y rocas. Barra rápida: 5 huecos (teclas 1-5).</div><div class="grid">`;
  if(!ids.length)h+='<p class="mut">Vacía. Camina sobre ramas y piedras del suelo para recogerlas.</p>';
  for(const id of ids){const f=FOODS[id],wp=WEAPCYCLE.includes(id);h+=`<div class="it"><span class="em">${IT[id][1]}</span><b>${IT[id][0]}</b><em>×${P.inv[id]}</em>${f?`<button data-a="eat" data-k="${id}">Comer</button>`:''}${wp?`<button data-a="equip" data-k="${id}">${P.weapon===id?'Equipada':'Equipar'}</button>`:''}${HOTW.includes(id)?`<button data-a="hot" data-k="${id}">${P.hot.includes(id)?'Quitar de barra':'📌 A la barra'}</button>`:''}</div>`}
  h+='</div>';
  h+='<h4>Comida activa ('+P.foods.length+'/3)</h4>'+(P.foods.length?P.foods.map(f=>`<div class="mut">${IT[f.id][1]} ${IT[f.id][0]} · ${Math.ceil(f.rem/60)} min</div>`).join(''):'<p class="mut">Comer sube tu vida y estamina máximas durante un rato. Máximo 3 comidas distintas a la vez.</p>')}
 else if(sheetTab==='craft'){
  for(const r of RECIPES.filter(r=>!r.st)){const w=whyNot(r),it=IT[r.id];h+=`<div class="rc ${w?'off':''}"><span style="font-size:24px">${it[1]}</span><div class="nm">${it[0]}<div class="cs">${costHTML(r.cost)}</div>${w?`<div class="why">${w}</div>`:''}</div><button data-a="craft" data-k="${r.id}">Crear</button></div>`}
  h+='<p class="mut">Aquí solo lo básico. Lanza, escudo, capa, pico, comida y espada se fabrican en su estación: acércate y pulsa ✋. Las estaciones se construyen con el martillo (🔨).</p>'}
 else if(sheetTab==='st'){h+='<p class="mut">Estación de trabajo: aquí se fabrican los objetos avanzados.</p>';for(const r of RECIPES.filter(r=>r.st===stOpen)){const w=whyNot(r),it=IT[r.id];h+=`<div class="rc ${w?'off':''}"><span style="font-size:24px">${it[1]}</span><div class="nm">${it[0]}<div class="cs">${costHTML(r.cost)}</div>${w?`<div class="why">${w}</div>`:''}</div><button data-a="craft" data-k="${r.id}">Crear</button></div>`}}
 else if(sheetTab==='chest'&&chestOpen){
  h+='<h4>Mochila (toca para guardar)</h4><div class="grid">'+Object.keys(P.inv).map(id=>`<div class="it" data-a="put" data-k="${id}"><span class="em">${IT[id][1]}</span><b>${IT[id][0]}</b><em>×${P.inv[id]}</em></div>`).join('')+'</div>';
  h+='<h4>Cofre (toca para sacar)</h4><div class="grid">'+(Object.keys(chestOpen.items).map(id=>`<div class="it" data-a="take" data-k="${id}"><span class="em">${IT[id][1]}</span><b>${IT[id][0]}</b><em>×${chestOpen.items[id]}</em></div>`).join('')||'<p class="mut">Vacío.</p>')+'</div>'}
 else if(sheetTab==='guide'){
  h+='<h4>Objetivos</h4>'+GOALS.map((g,i)=>{const ok=i<GOALS.length-1&&g[1]();return`<div class="gl ${ok?'ok':''}">${ok?'✓':'○'} ${g[0]}</div>`}).join('');
  h+='<h4>Construcción</h4><p class="mut">Cada pieza tiene estabilidad: 100% en el suelo y menos cuanto más lejos del apoyo. 🟢 sólida · 🟡 en riesgo · 🔴 se caerá. La madera aguanta ~3 casillas en voladizo; la piedra más; las vigas más aún. Si quitas un apoyo, lo de arriba se derrumba y puede herir.</p>'
  +'<h4>Combate</h4><p class="mut">Los enemigos marcan en rojo dónde van a golpear. Esquiva (💨) da invulnerabilidad un instante. Mantén 🛡️ para bloquear; si lo pulsas justo antes del golpe haces parry: el enemigo queda aturdido y tu siguiente golpe es crítico. Los árboles al caer dañan todo en su camino, incluido a ti.</p>'}
 else if(sheetTab==='menu'){
  h+=`<div class="mn"><button data-a="save">💾 Guardar ahora</button><button data-a="mute">${muted?'🔇 Sonido apagado':'🔊 Sonido activado'}</button><button data-a="theme">🎨 Tema de los paneles</button><button data-a="newgame">🗑 Nueva partida</button></div><p class="mut">La partida se guarda sola cada pocos segundos en este navegador.</p>`}
 $('shc').innerHTML=h}
$('sheet').addEventListener('click',e=>{
 const b=e.target.closest('[data-a]');if(!b)return;const a=b.dataset.a,k=b.dataset.k;
 if(a==='tab'){sheetTab=k;renderSheet()}else if(a==='close')closeSheet();else if(a==='eat')eat(k);
 else if(a==='equip'){P.weapon=k;renderHot();renderSheet()}
 else if(a==='hot'){const i=P.hot.indexOf(k);if(i>=0)P.hot[i]=null;else{let j=P.hot.indexOf(null);if(j<0){j=Math.max(0,P.hot.indexOf(P.weapon));}P.hot[j]=k}renderHot();renderSheet()}else if(a==='craft')craft(k);
 else if(a==='put'&&chestOpen){chestOpen.items[k]=(chestOpen.items[k]|0)+P.inv[k];delete P.inv[k];renderSheet()}
 else if(a==='take'&&chestOpen){P.inv[k]=(P.inv[k]|0)+chestOpen.items[k];delete chestOpen.items[k];renderSheet()}
 else if(a==='save'){save();toast('Partida guardada')}
 else if(a==='mute'){muted=!muted;renderSheet()}
 else if(a==='theme'){const r=document.documentElement,cur=r.getAttribute('data-theme');r.setAttribute('data-theme',cur==='dark'?'light':'dark')}
 else if(a==='newgame'){if(confirm('¿Borrar la partida y empezar de nuevo?')){try{localStorage.removeItem('ashfall_v1')}catch(x){}startNew()}}});
$('bpcs').addEventListener('click',e=>{const b=e.target.closest('[data-p]');if(!b)return;build.type=b.dataset.p;build.demo=false;if(BT[build.type].station||BT[build.type].slab)build.z=0;refreshBuild(true)});
/* ---------- ENTRADA ---------- */
function press(id,on,off){const el=$(id);el.addEventListener('pointerdown',e=>{e.preventDefault();snd(1,.001,'sine',.0001);el.classList.add('dn');on()});const up=e=>{el.classList.remove('dn');if(off)off()};el.addEventListener('pointerup',up);el.addEventListener('pointercancel',up);el.addEventListener('pointerleave',up);el.addEventListener('contextmenu',e=>e.preventDefault())}
press('aAtk',()=>{IN.atk=true},()=>{IN.atk=false});
press('aGuard',()=>{IN.guard=true},()=>{IN.guard=false});
press('aDodge',dodge);press('aUse',useAct);
press('bBag',()=>{$('sheet').classList.contains('on')?closeSheet():openSheet('bag')});
press('bBuild',()=>setBuild(!build.on));press('bWeap',cycleWeapon);
press('bMenu',()=>openSheet('menu'));press('bZoom',()=>{zoomIdx=(zoomIdx+1)%3;resize()});
press('bUp',()=>{build.z=Math.min(7,build.z+1);if(BT[build.type].station||BT[build.type].slab)build.z=0;refreshBuild()});
press('bDn',()=>{build.z=Math.max(0,build.z-1);refreshBuild()});
press('bOk',placeBlock);press('bRot',()=>{const ei=edgeInfo();build.edge=(((build.edge!=null&&build.edgeCell===ei.cell)?build.edge:ei.e)+1)%4;build.edgeCell=ei.cell;refreshBuild()});press('bDem',()=>{build.demo=!build.demo;refreshBuild(true)});
const joyEl=$('joy');
function pt(e){const r=cv.getBoundingClientRect();return{x:e.clientX-r.left,y:e.clientY-r.top}}
function setCur(x,y){const t=BT[build.type],w=s2w(x,y,t.station||t.slab?0:build.z*WH);build.wx=w[0];build.wy=w[1];build.cx=clamp(Math.floor(w[0]),0,N-1);build.cy=clamp(Math.floor(w[1]),0,N-1);build.manual=true;refreshBuild()}
cv.addEventListener('pointerdown',e=>{
 if(!running)return;const p=pt(e);
 if(build.on&&(e.pointerType==='mouse'||p.x>W*.5)){setCur(p.x,p.y);curPtr=e.pointerId;cv.setPointerCapture(e.pointerId);return}
 if(joy.id===null&&(e.pointerType==='mouse'||p.x<W*.5)){joy.id=e.pointerId;joy.ox=p.x;joy.oy=p.y;cv.setPointerCapture(e.pointerId);joyEl.style.display='block';joyEl.style.left=p.x+'px';joyEl.style.top=p.y+'px';joyEl.firstElementChild.style.transform='translate(0,0)'}});
cv.addEventListener('pointermove',e=>{
 const p=pt(e);
 if(e.pointerId===joy.id){let dx=p.x-joy.ox,dy=p.y-joy.oy;const R=50,d=Math.hypot(dx,dy);if(d>R){dx=dx/d*R;dy=dy/d*R}IN.ix=dx/R;IN.iy=dy/R;joyEl.firstElementChild.style.transform=`translate(${dx}px,${dy}px)`}
 else if(e.pointerId===curPtr)setCur(p.x,p.y)});
const endP=e=>{if(e.pointerId===joy.id){joy.id=null;IN.ix=0;IN.iy=0;joyEl.style.display='none'}if(e.pointerId===curPtr)curPtr=null};
cv.addEventListener('pointerup',endP);cv.addEventListener('pointercancel',endP);
window.addEventListener('keydown',e=>{
 const k=e.key.toLowerCase();if(k===' '||k.startsWith('arrow'))e.preventDefault();if(e.repeat&&k!=='j')return;
 IN.keys[k]=true;
 if(!running)return;
 if(k===' ')dodge();else if(k==='j')IN.atk=true;else if(k==='k'||k==='shift')IN.guard=true;else if(k==='e')useAct();
 else if(k==='b')setBuild(!build.on);else if(k==='i'||k==='tab'){e.preventDefault();$('sheet').classList.contains('on')?closeSheet():openSheet('bag')}
 else if(k==='q')cycleWeapon();else if(k>='1'&&k<='5')hotSel(+k-1);else if(k==='escape')closeSheet();
 else if(build.on&&(k==='enter'))placeBlock();else if(build.on&&k==='r')build.z=Math.min(7,build.z+1);else if(build.on&&k==='f')build.z=Math.max(0,build.z-1)});
window.addEventListener('keyup',e=>{const k=e.key.toLowerCase();IN.keys[k]=false;if(k==='j')IN.atk=false;if(k==='k'||k==='shift')IN.guard=false});
window.addEventListener('blur',()=>{IN.keys={};IN.atk=false;IN.guard=false});
document.addEventListener('contextmenu',e=>e.preventDefault());
/* ---------- GUARDADO ---------- */
const SAVEKEY='ashfall_v2';
function save(){
 if(!running)return;
 try{const o={v:1,seed,T,S,p:{x:P.x,y:P.y,hp:P.hp,st:P.st,inv:P.inv,foods:P.foods,weapon:P.weapon,debuff:P.debuff,dead:P.dead,hot:P.hot},removed:[...removed],blocks:[...blocks.values()].map(b=>[b.x,b.y,b.z,b.type,b.items||null,b.o|0,b.c|0]),tomb,ex:Array.prototype.map.call(explored,v=>v).join('')};
  localStorage.setItem(SAVEKEY,JSON.stringify(o))}catch(e){}}
function hasSave(){try{return!!localStorage.getItem(SAVEKEY)}catch(e){return false}}
function load(){
 try{const o=JSON.parse(localStorage.getItem(SAVEKEY));if(!o||o.v!==1)return false;
  genWorld(o.seed);newPlayer();newState();Object.assign(S,o.S);S.f=Object.assign({boss:false,max3:false},S.f);T=o.T;
  for(const id of o.removed){removed.add(id);if(res[id])res[id].gone=true}
  blocks=new Map();for(const b of o.blocks){if(!BT[b[3]])continue;if((BT[b[3]].wall||BT[b[3]].slab)&&!b[6])continue;const blk={x:b[0],y:b[1],z:b[2],type:b[3],stab:1,o:b[5]|0,c:b[6]|0};if(b[4])blk.items=b[4];else if(b[3]==='cofre')blk.items={};blocks.set(bkey(blk),blk)}
  rebuildStations();recomputeStability();
  Object.assign(P,{x:o.p.x,y:o.p.y,hp:o.p.hp,st:o.p.st,inv:o.p.inv,foods:o.p.foods,weapon:o.p.weapon,debuff:o.p.debuff||0,hot:o.p.hot||[null,null,null,null,null]});for(const id of HOTW)if(P.inv[id])hotAdd(id);hotK='';
  tomb=o.tomb||null;E=[];boss=null;debris=[];
  if(o.ex)for(let i=0;i<N*N;i++)if(o.ex.charCodeAt(i)===49){explored[i]=1;paintMM(i)}
  mmDirty=true;return true}catch(e){return false}}
function startNew(){
 genWorld((Math.random()*1e9)|0);newPlayer();newState();blocks=new Map();stations=[];debris=[];E=[];boss=null;tomb=null;parts=[];floats=[];T={time:.4*DAYLEN,day:1};
 mmImg=mmx.createImageData(N,N);mmDirty=true;begin();toast('Camina sobre ramas 🪵 y piedras 🪨 para recogerlas',3500)}
function begin(){
 $('title').style.display='none';closeSheet();setBuild(false);running=true;camX=P.x;camY=P.y;camZ=elevAt(P.x,P.y);recalc();S.goal=0;lastGoal=-1;resize();save()}
function goFull(){try{const el=document.documentElement,f=el.requestFullscreen||el.webkitRequestFullscreen;if(f&&!document.fullscreenElement&&!document.webkitFullscreenElement){const q=f.call(el);if(q&&q.catch)q.catch(()=>{})}}catch(e){}}
$('tNew').addEventListener('click',()=>{goFull();try{localStorage.removeItem(SAVEKEY)}catch(e){}startNew()});
$('tCont').addEventListener('click',()=>{goFull();if(load())begin();else startNew()});
document.addEventListener('visibilitychange',()=>{if(document.hidden)save()});window.addEventListener('pagehide',save);
if(hasSave())$('tCont').style.display='block';
